import {StyleProp, TouchableOpacity, ViewStyle} from 'react-native';
import React, {useEffect} from 'react';
import {IconToggleOff, IconToggleOn} from '../../assets/images';

type Props = {
  isEnabled: boolean;
  onPress?: () => void;
  disable?: boolean;
  containerStyle?: StyleProp<ViewStyle>;
};

const SwitchCM = ({isEnabled, onPress, containerStyle, disable}: Props) => {
  return (
    <TouchableOpacity
      disabled={disable}
      onPress={onPress}
      style={containerStyle}>
      {isEnabled ? (
        <IconToggleOn width={40} height={40} />
      ) : (
        <IconToggleOff width={40} height={40} />
      )}
    </TouchableOpacity>
  );
};

export default SwitchCM;
